async function load(){if(!AUTH?.token){showLogin();return}const lb=$('loadingBar'),key='kgfarmsmini_bundle_v47_'+(USER_ROLE||'unknown'),stampKey=key+'_stamp';let hadCache=false;try{const cached=localStorage.getItem(key);if(cached){const j=JSON.parse(cached);if(j&&j.success&&j.role){S=j;COMPANY=j.company||COMPANY;USER_ROLE=j.role;hadCache=true;applyRole();render()}}}catch(e){}const last=Number(localStorage.getItem(stampKey)||0);if(hadCache&&Date.now()-last<30000)return;if(lb&&!hadCache)lb.classList.add('show');try{let r=await fetch(API+'?t='+Date.now()+'&token='+encodeURIComponent(AUTH.token),{cache:'no-store'}),j=await r.json();if(!j.success){if(['LOGIN_REQUIRED','SESSION_EXPIRED'].includes(j.error)){logout();return}throw Error(j.error||'Unable to load data')}S=j;COMPANY=j.company||COMPANY;USER_ROLE=j.role||USER_ROLE;applyRole();try{localStorage.setItem(key,JSON.stringify(j));localStorage.setItem(stampKey,String(Date.now()))}catch(e){}render()}catch(e){if(!hadCache)toast(e.message||'Unable to load KG Farms.','error')}finally{lb&&lb.classList.remove('show')}}
async function doLogin(){let u=$('loginUsername').value.trim(),p=$('loginPassword').value,err=$('loginError'),btn=$('loginBtn');err.style.display='none';if(!u||!p){err.textContent='Enter username and password';err.style.display='block';return}btn.disabled=true;try{let q=new URLSearchParams({action:'login',username:u,password:p});let r=await fetch(API,{method:'POST',body:q.toString(),headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'}});let j=await r.json();if(!j.success)throw Error(j.error||'Login failed');AUTH={token:j.token,username:j.username,role:j.role};USER_ROLE=j.role;localStorage.setItem('kgfarms_auth',JSON.stringify(AUTH));$('loginScreen').style.display='none';$('appShell').style.display='block';applyRole();await load();routeFromHash()}catch(e){err.textContent=e.message;err.style.display='block'}finally{btn.disabled=false}}
