async function submitSaleEntry(){let tid=$('seTrader').value,t=(S.traders||[]).find(x=>x.traderId===tid),date=$('seDate').value,birds=+$('seBirds').value,kg=+$('seKg').value,type=$('seType').value,meta=selectedSaleMetaFromModal();if(!t||!date||!meta.vehicle||!Number.isInteger(birds)||birds<=0||!Number.isFinite(kg)||kg<=0){toast('Enter date, vehicle, trader, birds and kg','error');return}let b=saleBatch(),used=saleTotals().birds;if(used+birds>b.currentBirds+20){toast('Bird count exceeds live birds by more than the ±20 tolerance','error');return}SALE_ENTRIES.push({date,traderId:tid,traderName:t.traderName,birds,kg,birdType:type});let snapshot=SALE_ENTRIES.map(x=>({...x}));closeModal();renderSalesPage();toast('Entry added','success');if(SALE_EDIT_ID){let saleId=SALE_EDIT_ID;SALE_DRAFT_SAVE_PROMISE=SALE_DRAFT_SAVE_PROMISE.then(async()=>{try{await saveCurrentCompletedSale();toast('Sale entry saved','success')}catch(e){toast(e.message,'error')}});return}let firstDate=snapshot[0]?.date||date;SALE_DRAFT_SAVE_PROMISE=SALE_DRAFT_SAVE_PROMISE.then(async()=>{try{let r=await post({action:'saveSaleDraft',saleId:SALE_DRAFT_ID,batchId:b.batchId,saleDate:firstDate,vehicleNo:meta.vehicle,supervisor:meta.supervisor,items:JSON.stringify(snapshot)});SALE_DRAFT_ID=r.saleId;S.sales=S.sales||[];let old=S.sales.find(x=>x.saleId===r.saleId);let d={saleId:r.saleId,saleDate:firstDate,batchId:b.batchId,farmName:b.farmName,status:'DRAFT',vehicleNo:meta.vehicle,supervisor:meta.supervisor};if(old)Object.assign(old,d);else S.sales.push(d);try{localStorage.setItem('kgfarmsmini_bundle_v47',JSON.stringify(S))}catch(e){}renderSalesPage()}catch(e){toast('Draft save failed: '+e.message,'error')}})}

function editSaleEntry(i){let x=SALE_ENTRIES[i];if(!x)return;let traders=(S.traders||[]).filter(t=>String(t.status||'Active').toLowerCase()==='active');modal(`<div class=head><b>Edit Trader Sale</b><button class=secondary onclick=closeModal()>✕</button></div><div class=form><label>Date<input id="eeDate" type="date" value="${esc(x.date)}"></label><label>Trader<select id="eeTrader">${traders.map(t=>`<option value="${esc(t.traderId)}" ${t.traderId===x.traderId?'selected':''}>${esc(t.traderName)}</option>`).join('')}</select></label><label>Kg<input id="eeKg" type="number" min="0.1" step="0.1" value="${x.kg}"></label><label>No. of Birds<input id="eeBirds" type="number" min="1" step="1" value="${x.birds}"></label><label>Bird Type<select id="eeType"><option value="Good" ${x.birdType==='Good'?'selected':''}>Good</option><option value="Weak" ${x.birdType==='Weak'?'selected':''}>Weak</option></select></label></div><div class=actions><button class=secondary onclick=closeModal()>Cancel</button><button onclick="saveSaleEntryEdit(${i})">Save</button></div>`)}
async function saveSaleEntryEdit(i){let x=SALE_ENTRIES[i],tid=$('eeTrader').value,t=(S.traders||[]).find(a=>a.traderId===tid),date=$('eeDate').value,kg=+$('eeKg').value,birds=+$('eeBirds').value;if(!x||!t||!date||!Number.isInteger(birds)||birds<=0||!Number.isFinite(kg)||kg<=0){toast('Enter valid trader sale details','error');return}let otherBirds=saleTotals().birds-(+x.birds||0);if(otherBirds+birds>saleBatch().currentBirds+20){toast('Bird count exceeds live birds by more than the ±20 tolerance','error');return}SALE_ENTRIES[i]={...x,date,traderId:tid,traderName:t.traderName,kg,birds,birdType:$('eeType').value};let snapshot=SALE_ENTRIES.map(x=>({...x}));closeModal();renderSalesPage();toast('Entry updated','success');if(SALE_EDIT_ID){SALE_DRAFT_SAVE_PROMISE=SALE_DRAFT_SAVE_PROMISE.then(async()=>{try{await saveCurrentCompletedSale();toast('Sale updated','success')}catch(e){toast(e.message,'error')}})}else{let d=(S.sales||[]).find(x=>x.saleId===SALE_DRAFT_ID)||{},vehicle=d.vehicleNo||'',supervisor=d.supervisor||'';SALE_DRAFT_SAVE_PROMISE=SALE_DRAFT_SAVE_PROMISE.then(async()=>{try{let r=await post({action:'saveSaleDraft',saleId:SALE_DRAFT_ID,batchId:saleBatch().batchId,saleDate:snapshot[0]?.date||dateToday(),vehicleNo:vehicle,supervisor:supervisor,items:JSON.stringify(snapshot)});SALE_DRAFT_ID=r.saleId;toast('Draft updated','success')}catch(e){toast('Draft save failed: '+e.message,'error')}})}}

async function removeSaleEntry(i){SALE_ENTRIES.splice(i,1);if(SALE_EDIT_ID){try{if(!SALE_ENTRIES.length){toast('A completed sale must have at least one trader entry','error');return}await saveCurrentCompletedSale();await load()}catch(e){toast(e.message,'error')}}else if(SALE_DRAFT_ID&&SALE_ENTRIES.length){try{let b=saleBatch(),d=(S.sales||[]).find(x=>x.saleId===SALE_DRAFT_ID)||{},vehicle=d.vehicleNo||'',supervisor=d.supervisor||'';await post({action:'saveSaleDraft',saleId:SALE_DRAFT_ID,batchId:b.batchId,saleDate:SALE_ENTRIES[0]?.date||d.saleDate||dateToday(),vehicleNo:vehicle,supervisor:supervisor,items:JSON.stringify(SALE_ENTRIES)});await load()}catch(e){toast(e.message,'error')}}else if(SALE_DRAFT_ID){await deleteSaleDraftConfirm(SALE_DRAFT_ID);SALE_DRAFT_ID=''}renderSalesPage()}
async function saveCurrentCompletedSale(){let b=saleBatch(),sale=(S.sales||[]).find(x=>x.saleId===SALE_EDIT_ID);if(!b||!sale)throw Error('Sale not found');let pm=+sale.postMortality||0,cull=+sale.cullBirds||0;return post({action:'updateSale',saleId:SALE_EDIT_ID,batchId:b.batchId,saleDate:SALE_ENTRIES[0]?.date||sale.saleDate||dateToday(),feedReturnKg:+sale.feedReturnKg||0,postMortality:pm,cullBirds:cull,manualIncentive:+sale.extraIncentive||0,vehicleNo:sale.vehicleNo||'',supervisor:sale.supervisor||'',items:JSON.stringify(SALE_ENTRIES)})}
