async function finalizeSale(){if(window.__saleSaving)return;window.__saleSaving=true;try{let b=saleBatch();if(!b)return;let t=saleTotals();if(!SALE_ENTRIES.length){toast('Add at least one trader entry','error');return}let pm=+$('salePostMort').value||0,cull=+$('saleCull').value||0,saleDate=SALE_ENTRIES[0]?.date||dateToday(),sale=SALE_EDIT_ID?((S.sales||[]).find(x=>x.saleId===SALE_EDIT_ID)||{}):((S.sales||[]).find(x=>x.saleId===SALE_DRAFT_ID)||{}),vehicle=sale.vehicleNo||'',supervisor=sale.supervisor||'';let balance=b.currentBirds-t.birds-pm-cull;if(Math.abs(balance)>20&&!confirm('Bird reconciliation is '+(balance>0?'+':'')+balance+' birds. This exceeds ±20 and will be flagged for debit. Continue?'))return;if(!vehicle){toast('Vehicle No. is required. Add it when adding the trader entry.','error');return}if(!confirm((SALE_EDIT_ID?'Save changes to':'Complete sale for')+' '+b.farmName+'?'))return;let action=SALE_EDIT_ID?'updateSale':'createSale';let r=await post({action,saleId:SALE_EDIT_ID||undefined,batchId:b.batchId,saleDate,feedReturnKg:SALE_EDIT_ID?(sale.feedReturnKg||0):0,postMortality:pm,cullBirds:cull,manualIncentive:SALE_EDIT_ID?(sale.extraIncentive||0):0,vehicleNo:vehicle,supervisor:supervisor,items:JSON.stringify(SALE_ENTRIES)});if(!SALE_EDIT_ID&&SALE_DRAFT_ID){try{await post({action:'deleteSaleDraft',saleId:SALE_DRAFT_ID})}catch(e){}}SALE_ENTRIES=[];SALE_DRAFT_ID='';SALE_EDIT_ID='';await load();toast(`Sale ${r.saleId} saved`,'success');page('sales');renderSalesPage()}catch(e){toast(e.message,'error')}}
function renderSalesHistory(){let out=$('salesHistory');if(!out)return;let drafts=(S.sales||[]).filter(x=>String(x.status).toUpperCase()==='DRAFT').slice().reverse(),activeIds=new Set((S.batches||[]).map(b=>b.batchId)),sales=Array.from(new Map((S.sales||[]).filter(x=>String(x.status).toUpperCase()==='COMPLETED'&&activeIds.has(x.batchId)).map(x=>[x.batchId,x])).values()).slice().reverse().slice(0,8);let draftHtml=drafts.length?`<div class="saleDraftBox"><div class="sectionHead"><h3>Saved Drafts</h3><span class="muted">Entries are saved automatically</span></div>${drafts.map(x=>`<div class="saleHistoryRow draftRow"><div class="saleHistoryTop"><div><div class="saleHistoryName">${esc(x.farmName)}</div><div class="saleHistoryMeta">${esc(x.saleId)} • ${esc(x.saleDate)} • ${esc(x.batchId)}</div></div><span class="badge pending">DRAFT</span></div><div class="mobileActions"><button onclick="resumeSaleDraft('${esc(x.saleId)}')">Resume</button><button class="secondary" onclick="deleteSaleDraftConfirm('${esc(x.saleId)}')">Delete</button></div></div>`).join('')}</div>`:'';let html=sales.length?sales.map(x=>`<div class="saleHistoryRow"><div class="saleHistoryTop"><div><div class="saleHistoryName">${esc(x.farmName)}</div><div class="saleHistoryMeta">${esc(x.saleId)} • ${esc(x.saleDate)} • ${esc(x.batchId)} • ${esc(x.vehicleNo||'')} • ${esc(x.supervisor||'')}</div></div><span class="badge">${esc(x.fcrSlab||'Completed')}</span></div><div class="saleHistoryStats"><div><span>BIRDS</span><b>${x.birdsSold}</b></div><div><span>SALE KG</span><b>${(+x.totalSaleKg).toFixed(1)}</b></div><div><span>AVG</span><b>${x.birdsSold?(+x.totalSaleKg/x.birdsSold).toFixed(2):'—'}</b></div></div><div class="mobileActions"><button class="secondary" onclick="editSale('${esc(x.saleId)}')">Edit Sale</button><button class="secondary dangerBtn" onclick="deleteSaleConfirm('${esc(x.saleId)}')">Delete Sale</button></div></div>`).join(''):'<div class="emptyState">No completed sales yet.</div>';out.innerHTML=draftHtml+`<div class="sectionHead" style="margin-top:14px"><h3>Completed Sales</h3></div>`+html}
function fcrRateForSale(fcr){let f=S.settings?.fcr||{base:1.6,baseRate:10,stepRate:.2};let x=Math.round(Number(fcr)*100)/100;if(!Number.isFinite(x))return 0;return Math.max(0,Math.round((f.baseRate+((f.base-x)/.01)*f.stepRate)*100)/100)}
